/**
 * ER-07-03: sedan slalom fixture (07 §3.6, §5.7).
 *
 * One car on a flat plane: full throttle until 30 m/s, a 150 m sinusoidal
 * slalom between kerbs, then full brake. Records the acceleration time, the
 * minimum chassis up-axis, the longest per-wheel air gap, the final speed and
 * the state hash. Recorded values are generated by this test, not invented.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import type {
  BodyHandle,
  VehicleHandle,
  WheelDesc,
} from "../../src/index.js";
import {
  DT,
  bodyState,
  dynamicBox,
  ground,
  init,
  makeWorld,
  staticBox,
  v3,
  vehicleState,
} from "../support/world.js";

interface VehicleFixture {
  readonly world: {
    readonly gravity: readonly number[];
  };
  readonly course: {
    readonly groundTop: number;
    readonly groundHalfExtents: readonly number[];
    readonly slalomLengthM: number;
    readonly laneHalfWidthM: number;
    readonly kerbOffsetM: number;
    readonly kerbHalfExtents: readonly number[];
    readonly kerbSpacingM: number;
  };
  readonly vehicle: {
    readonly chassisHalfExtents: readonly number[];
    readonly chassisMass: number;
    readonly start: readonly number[];
    readonly wheels: readonly {
      readonly localPosition: readonly number[];
      readonly radius: number;
      readonly width: number;
      readonly suspensionRestLength: number;
      readonly suspensionStiffness: number;
      readonly suspensionDamping: number;
      readonly maxTravel: number;
      readonly steerable: boolean;
      readonly driven: boolean;
      readonly friction: number;
    }[];
    readonly engineForce: number;
    readonly reverseForce: number;
    readonly brakeForce: number;
    readonly maxSteerDegrees: number;
    readonly steerRateDegreesPerSecond: number;
    readonly topSpeed: number;
    readonly downforce: number;
  };
  readonly control: {
    readonly accelerateThrottle: number;
    readonly accelerateMaxTicks: number;
    readonly targetSpeed: number;
    readonly slalomThrottle: number;
    readonly slalomSteerAmplitude: number;
    readonly slalomWavelengthM: number;
    readonly brakeMaxTicks: number;
  };
  readonly recorded: {
    readonly timeTo30Ticks: number | null;
    readonly timeTo30Seconds: number | null;
    readonly maxSpeed: number | null;
    readonly slalomDistanceM: number | null;
    readonly slalomMaxAbsX: number | null;
    readonly minUpY: number | null;
    readonly maxWheelAirTicks: number | null;
    readonly stopSpeed: number | null;
    readonly brakeTicks: number | null;
    readonly finalHash: number | null;
  };
}

const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/vehicle-slalom.json", import.meta.url),
    "utf8",
  ),
) as VehicleFixture;

function makeCar(world: ReturnType<typeof makeWorld>): {
  chassis: BodyHandle;
  vehicle: VehicleHandle;
} {
  const v = fixture.vehicle;
  const chassis = dynamicBox(
    world,
    v3(v.start[0]!, v.start[1]!, v.start[2]!),
    v3(
      v.chassisHalfExtents[0]!,
      v.chassisHalfExtents[1]!,
      v.chassisHalfExtents[2]!,
    ),
    { mass: v.chassisMass, canSleep: false },
    { friction: 0.4 },
  );
  const wheels: WheelDesc[] = v.wheels.map((wheel) => ({
    ...wheel,
    localPosition: v3(
      wheel.localPosition[0]!,
      wheel.localPosition[1]!,
      wheel.localPosition[2]!,
    ),
  }));
  const vehicle = world.createVehicle({
    chassis: chassis.body,
    wheels,
    engineForce: v.engineForce,
    reverseForce: v.reverseForce,
    brakeForce: v.brakeForce,
    maxSteerDegrees: v.maxSteerDegrees,
    steerRateDegreesPerSecond: v.steerRateDegreesPerSecond,
    topSpeed: v.topSpeed,
    downforce: v.downforce,
  });
  return { chassis: chassis.body, vehicle };
}

/** Chassis up-axis Y from a unit quaternion (02 convention). */
function upY(q: { x: number; y: number; z: number; w: number }): number {
  return 1 - 2 * (q.x * q.x + q.z * q.z);
}

beforeAll(async () => {
  await init();
});

describe("vehicle-slalom fixture", () => {
  test(
    "[ER-07-03] the sedan reaches 30 m/s, completes the 150 m slalom upright, and brakes below 0.2 m/s",
    () => {
      const world = makeWorld({
        gravity: v3(
          fixture.world.gravity[0]!,
          fixture.world.gravity[1]!,
          fixture.world.gravity[2]!,
        ),
      });
      const course = fixture.course;
      ground(
        world,
        course.groundTop,
        v3(
          course.groundHalfExtents[0]!,
          course.groundHalfExtents[1]!,
          course.groundHalfExtents[2]!,
        ),
        { friction: 0.9 },
      );
      const kerbX = course.kerbOffsetM;
      for (
        let z = -course.kerbSpacingM;
        z >= -600;
        z -= course.kerbSpacingM
      ) {
        for (const side of [-1, 1]) {
          staticBox(
            world,
            v3(side * kerbX, course.kerbHalfExtents[1]!, z),
            v3(
              course.kerbHalfExtents[0]!,
              course.kerbHalfExtents[1]!,
              course.kerbHalfExtents[2]!,
            ),
            { friction: 0.8 },
          );
        }
      }

      const car = makeCar(world);
      const chassisState = bodyState();
      const telemetry = vehicleState();
      const control = fixture.control;

      let ticks = 0;
      let speed = 0;
      let maxSpeed = -Infinity;
      let timeTo30Ticks = -1;
      const advance = (input: {
        throttle: number;
        steering: number;
        brake: number;
      }) => {
        world.setVehicleInput(car.vehicle, input);
        world.step(DT);
        world.readVehicle(car.vehicle, telemetry);
        world.readBody(car.chassis, chassisState);
        speed = telemetry.speed;
        if (speed > maxSpeed) maxSpeed = speed;
        ticks += 1;
      };

      /* Accelerate straight to 30 m/s. */
      while (
        ticks < control.accelerateMaxTicks &&
        speed < control.targetSpeed
      ) {
        advance({
          throttle: control.accelerateThrottle,
          steering: 0,
          brake: 0,
        });
        if (speed >= control.targetSpeed) timeTo30Ticks = ticks;
      }

      /* Slalom for 150 m, tracking roll, lane and wheel contact. */
      let distance = 0;
      let lastX = chassisState.position.x;
      let lastZ = chassisState.position.z;
      let slalomMaxAbsX = 0;
      let minUp = Infinity;
      const airRun = [0, 0, 0, 0];
      let maxAir = 0;
      const trackAir = () => {
        for (let i = 0; i < airRun.length; i += 1) {
          airRun[i] = telemetry.wheels[i]!.contact ? 0 : airRun[i]! + 1;
          if (airRun[i]! > maxAir) maxAir = airRun[i]!;
        }
      };
      while (distance < course.slalomLengthM && ticks < 3000) {
        const steer =
          control.slalomSteerAmplitude *
          Math.sin((2 * Math.PI * distance) / control.slalomWavelengthM);
        advance({
          throttle: control.slalomThrottle,
          steering: steer,
          brake: 0,
        });
        distance += Math.hypot(
          chassisState.position.x - lastX,
          chassisState.position.z - lastZ,
        );
        lastX = chassisState.position.x;
        lastZ = chassisState.position.z;
        slalomMaxAbsX = Math.max(slalomMaxAbsX, Math.abs(lastX));
        minUp = Math.min(minUp, upY(chassisState.rotation));
        trackAir();
      }

      /* Brake to below 0.2 m/s. */
      let brakeTicks = 0;
      while (Math.abs(speed) > 0.2 && brakeTicks < control.brakeMaxTicks) {
        advance({ throttle: 0, steering: 0, brake: 1 });
        brakeTicks += 1;
        minUp = Math.min(minUp, upY(chassisState.rotation));
        trackAir();
      }
      const stopSpeed = Math.abs(speed);

      expect(timeTo30Ticks).toBeGreaterThanOrEqual(0);
      expect(timeTo30Ticks).toBeLessThanOrEqual(control.accelerateMaxTicks);
      expect(distance).toBeGreaterThanOrEqual(course.slalomLengthM);
      expect(slalomMaxAbsX).toBeLessThanOrEqual(course.laneHalfWidthM);
      expect(minUp).toBeGreaterThan(0.5);
      expect(maxAir).toBeLessThanOrEqual(5);
      expect(stopSpeed).toBeLessThan(0.2);

      if (fixture.recorded.timeTo30Ticks !== null) {
        expect(timeTo30Ticks).toBe(fixture.recorded.timeTo30Ticks);
      }
      if (fixture.recorded.maxSpeed !== null) {
        expect(maxSpeed).toBeCloseTo(fixture.recorded.maxSpeed, 5);
      }
      if (fixture.recorded.slalomDistanceM !== null) {
        expect(distance).toBeCloseTo(fixture.recorded.slalomDistanceM, 5);
      }
      if (fixture.recorded.slalomMaxAbsX !== null) {
        expect(slalomMaxAbsX).toBeCloseTo(fixture.recorded.slalomMaxAbsX, 5);
      }
      if (fixture.recorded.minUpY !== null) {
        expect(minUp).toBeCloseTo(fixture.recorded.minUpY, 5);
      }
      if (fixture.recorded.maxWheelAirTicks !== null) {
        expect(maxAir).toBe(fixture.recorded.maxWheelAirTicks);
      }
      if (fixture.recorded.stopSpeed !== null) {
        expect(stopSpeed).toBeCloseTo(fixture.recorded.stopSpeed, 5);
      }
      if (fixture.recorded.brakeTicks !== null) {
        expect(brakeTicks).toBe(fixture.recorded.brakeTicks);
      }
      const finalHash = world.stateHash();
      if (fixture.recorded.finalHash !== null) {
        expect(finalHash).toBe(fixture.recorded.finalHash);
      }
      console.log(
        `[record vehicle-slalom] timeTo30Ticks=${timeTo30Ticks} timeTo30Seconds=${(timeTo30Ticks / 60).toFixed(4)} maxSpeed=${maxSpeed} distance=${distance} maxAbsX=${slalomMaxAbsX} minUpY=${minUp} maxWheelAirTicks=${maxAir} stopSpeed=${stopSpeed} brakeTicks=${brakeTicks} finalHash=${finalHash}`,
      );
      world.dispose();
    },
    300_000,
  );
});
